import{_ as r,C as n,o as s,c as l,a2 as a,b as h,w as i,a as o,E as d,a3 as p}from"./chunks/framework.DW4RdtHL.js";const c="/github-pages-docs/vitepress/dashboard-mockup.png",b=JSON.parse('{"title":"High Error Rate — Acme Order Service","description":"","frontmatter":{},"headers":[],"relativePath":"runbooks/high-error-rate.md","filePath":"runbooks/high-error-rate.md","lastUpdated":null}'),k={name:"runbooks/high-error-rate.md"};function g(u,e,F,m,C,y){const t=n("Mermaid");return s(),l("div",null,[e[1]||(e[1]=a('<h1 id="high-error-rate-—-acme-order-service" tabindex="-1">High Error Rate — Acme Order Service <a class="header-anchor" href="#high-error-rate-—-acme-order-service" aria-label="Permalink to &quot;High Error Rate — Acme Order Service&quot;">​</a></h1><p><strong>Status:</strong> Active · <strong>Owner:</strong> Platform Team · <strong>Last updated:</strong> 2026-09-01</p><p><strong>In this runbook:</strong></p><ul><li><a href="#alert-description">Alert description</a></li><li><a href="#severity">Severity</a></li><li><a href="#fast-path-mitigation">Fast-path mitigation</a></li><li><a href="#diagnostics">Diagnostics</a></li><li><a href="#decision-flowchart">Decision flowchart</a></li><li><a href="#escalation">Escalation</a></li></ul><h2 id="alert-description" tabindex="-1">Alert description <a class="header-anchor" href="#alert-description" aria-label="Permalink to &quot;Alert description&quot;">​</a></h2><p>The <strong>high error rate</strong> alert fires when the order service&#39;s 5xx rate exceeds 5% of requests over a 5-minute window. It is visible on the order service dashboard in the Acme Cloud console and pages the on-call engineer through PagerDuty (service <code>acme-order-service</code>).</p><p><img src="'+c+`" alt="Order service monitoring dashboard"></p><p><em>Figure 1: The Acme Cloud monitoring dashboard for the order service. The <code>5xx rate</code> panel (top left) is the panel that fires this alert; the <code>queue depth</code> panel (top right) distinguishes request-path failures from worker-path failures.</em></p><p>A sustained 5xx rate means customers are seeing failed order placements or failed status updates. Treat every firing as a real incident until diagnostics say otherwise.</p><h2 id="severity" tabindex="-1">Severity <a class="header-anchor" href="#severity" aria-label="Permalink to &quot;Severity&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Severity</th><th>Condition</th><th>Response</th></tr></thead><tbody><tr><td>SEV-1</td><td>5xx above 20% for 10 min</td><td>Page on-call; open incident in #ops</td></tr><tr><td>SEV-2</td><td>5xx above 5% for 10 min</td><td>Page on-call; mitigate within the hour</td></tr><tr><td>SEV-3</td><td>5xx above 2% sustained</td><td>Ticket; fix in business hours</td></tr></tbody></table><p>If customers are seeing failed orders, treat the alert as at least SEV-2 regardless of the measured rate.</p><h2 id="fast-path-mitigation" tabindex="-1">Fast-path mitigation <a class="header-anchor" href="#fast-path-mitigation" aria-label="Permalink to &quot;Fast-path mitigation&quot;">​</a></h2><p>Do these first, in order, before deep diagnostics:</p><ol><li><strong>Check for a recent deploy.</strong> If a release landed on the order service or its worker in the last 30 minutes, roll it back through the deployment pipeline (see the <code>deploy-release</code> SOP). This is the most common cause of this alert.</li><li><strong>Pause webhook delivery</strong> if the error spike is on the worker path (queue depth rising, request path healthy). Webhook failures retry automatically; pausing them stops the retry storm.</li><li><strong>Restart order service replicas one at a time</strong> if the database pool looks exhausted. A rolling restart resets connection pools without dropping capacity.</li><li><strong>Scale the worker up</strong> if queue depth is climbing and payment authorization is the bottleneck.</li></ol><h2 id="diagnostics" tabindex="-1">Diagnostics <a class="header-anchor" href="#diagnostics" aria-label="Permalink to &quot;Diagnostics&quot;">​</a></h2><h3 id="health-endpoints" tabindex="-1">Health endpoints <a class="header-anchor" href="#health-endpoints" aria-label="Permalink to &quot;Health endpoints&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Gateway and order service health checks</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sS</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/null</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -w</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;%{http_code} gateway\\n&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  https://api.acme.example/healthz</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sS</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/null</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -w</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;%{http_code} order-service\\n&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  https://order-service.internal.acme.example:8080/healthz</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -sS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://order-service.internal.acme.example:8080/readyz</span></span></code></pre></div><h3 id="logs" tabindex="-1">Logs <a class="header-anchor" href="#logs" aria-label="Permalink to &quot;Logs&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Recent errors from the order service (last 15 minutes)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">acme-logs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> query</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> order-service</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --since</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 15m</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;level=error OR status&gt;=500&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --limit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 50</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Dead-letter queue depth: a rising DLQ means worker failures</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">acme-queue</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> depth</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> orders-queue.internal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> order-events.dlq</span></span></code></pre></div><h3 id="metrics" tabindex="-1">Metrics <a class="header-anchor" href="#metrics" aria-label="Permalink to &quot;Metrics&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 5xx rate, last hour</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">acme-metrics</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> query</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --since</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1h</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;rate(http_requests_total{service=&quot;order-service&quot;,code=~&quot;5..&quot;}[5m])&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># p99 latency, last hour</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">acme-metrics</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> query</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --since</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1h</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;histogram_quantile(0.99, rate(http_request_duration_seconds_bucket{service=&quot;order-service&quot;}[5m]))&#39;</span></span></code></pre></div><p>If 5xx and p99 latency rise together, suspect the database or the gateway. If 5xx rises while latency stays flat, suspect application-level failures: a bad deploy, an exhausted pool, or a failed dependency call.</p><h2 id="decision-flowchart" tabindex="-1">Decision flowchart <a class="header-anchor" href="#decision-flowchart" aria-label="Permalink to &quot;Decision flowchart&quot;">​</a></h2>`,24)),(s(),h(p,null,{default:i(()=>[d(t,{id:"mermaid-161",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5BAlert%20fires%3A%205xx%20rate%20above%20threshold%5D%20--%3E%20B%7BError%20rate%20still%20rising%3F%7D%0A%20%20%20%20B%20--%3E%7CYes%7C%20C%5BCheck%20for%20deploy%20in%20last%2030%20min%5D%0A%20%20%20%20B%20--%3E%7CNo%2C%20elevated%20but%20flat%7C%20D%5BCheck%20dependency%20health%5D%0A%20%20%20%20C%20--%3E%20E%7BRecent%20deploy%20found%3F%7D%0A%20%20%20%20E%20--%3E%7CYes%7C%20F%5BRoll%20back%20through%20pipeline%5D%0A%20%20%20%20E%20--%3E%7CNo%7C%20D%0A%20%20%20%20D%20--%3E%20G%7BDependency%20degraded%3F%7D%0A%20%20%20%20G%20--%3E%7CYes%7C%20H%5BApply%20fast-path%20mitigation%5D%0A%20%20%20%20G%20--%3E%7CNo%7C%20I%5BInspect%20logs%20and%20metrics%5D%0A%20%20%20%20F%20--%3E%20J%7BError%20rate%20back%20to%20baseline%3F%7D%0A%20%20%20%20H%20--%3E%20J%0A%20%20%20%20I%20--%3E%20J%0A%20%20%20%20J%20--%3E%7CYes%7C%20K%5BMonitor%2030%20min%2C%20then%20close%20incident%5D%0A%20%20%20%20J%20--%3E%7CNo%7C%20L%5BEscalate%20to%20on-call%20lead%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="escalation" tabindex="-1">Escalation <a class="header-anchor" href="#escalation" aria-label="Permalink to &quot;Escalation&quot;">​</a></h2><ul><li><strong>First page:</strong> on-call engineer, PagerDuty service <code>acme-order-service</code></li><li><strong>Second page:</strong> on-call lead, if mitigation fails or the alert is SEV-1</li><li><strong>Third page:</strong> Platform Team, if the database or message queue is involved</li></ul><div class="danger custom-block"><p class="custom-block-title">When to escalate</p><p>Page the on-call lead immediately if any of the following is true:</p><ul><li>The error rate has not returned to baseline within 30 minutes of mitigation.</li><li>A rollback was attempted and did not recover the service.</li><li>Data integrity is at risk, for example orders stuck in <code>created</code> without payment.</li><li>You are unsure which component is failing after 15 minutes of diagnostics.</li></ul></div>',3))])}const v=r(k,[["render",g]]);export{b as __pageData,v as default};
